css:
/* Photo captions: a row of photographs with a short caption under each, centred. */
[data-bz-node="pc-band"] > .bz-container { max-width: calc(min(90vw, 1440px) + 32px); }
[data-bz-section="photo-captions"] .bz-block { padding-block: 0; }
[data-bz-section="photo-captions"] [data-bz-node="pc-row"] { display: flex; flex-wrap: wrap; justify-content: center; }
[data-bz-section="photo-captions"] [data-bz-node="pc-row"] > .bz-col { flex: 1 1 0; min-width: 0; grid-column: auto; }
[data-bz-section="photo-captions"] .bz-figure { margin: 0; display: flex; justify-content: center; }
[data-bz-section="photo-captions"] .bz-figure img { display: block; width: 100%; max-width: 213px; height: auto; border-radius: 0; }
[data-bz-section="photo-captions"] [data-bz-node="pc-row"] > .bz-col:first-child:nth-last-child(3) .bz-figure img, [data-bz-section="photo-captions"] [data-bz-node="pc-row"] > .bz-col:first-child:nth-last-child(3) ~ .bz-col .bz-figure img { max-width: 250px; }
[data-bz-section="photo-captions"] [data-bz-node^="pc-caption"] .bz-text p { margin: 20px auto 0; max-width: 200px; text-align: center; font: 400 0.8rem / 1.7 var(--font-body); color: #000; }
@media (max-width: 1100px) { [data-bz-section="photo-captions"] [data-bz-node="pc-row"] > .bz-col { flex: 0 0 33.333%; margin-bottom: 28px; } }
@media (max-width: 640px) { [data-bz-section="photo-captions"] [data-bz-node="pc-row"] > .bz-col { flex-basis: 50%; } }
[data-bz-section="photo-captions"] [data-bz-node="pc-row"] .bz-container { padding: 0; }
